INSERT INTO `company_info` (`id`, `company_name`, `description`, `image_name`, `country`) VALUES
(2, 'test company', 'China entertainment company. The company produces comedic videos in Chinese that can be between a few seconds to a few minutes. It has a dozen performing artists under management.', 'AdSmart_Company_177.JPG', 'China'),
(3, 'B Company', 'ZAG are recognized for asking the right questions to unearth exactly where brands need to be. By starting with strategy, zag makes sure every campaign, social post, and line of copy is crafted with an aligned purpose, eye-catching design, and powerful cre', 'AdSmart_Company_177.JPG', 'Macao'),
(4, 'Abc company', 'CREATIVE is an experienced team of Overachievers, Creative Geniuses & Dog Lovers. They are also very effective BRAND STORYTELLERS!', 'AdSmart_Company_993.JPG', 'US'),
(5, 'GoodCompany', 'Hong Kong Advertisement Comapny that it can provide full-service advertisement service. (Sucn ac Hong Kong Bus Advertisement service)', 'AdSmart_Company_353.JPG', 'Hong Kong'),
(6, 'GoodCompany', 'Hong Kong Advertisement Comapny that it can provide full-service advertisement service. (Sucn ac Hong Kong Bus Advertisement service)', 'AdSmart_Company_693.JPG', 'Hong Kong');
INSERT INTO `content` (`id`, `name`, `content_description`, `image_name`, `created_date`, `modified_date`, `created_username`, `updated_username`, `active`) VALUES
(6, 'AdSmart Value', 'AdSmart Platform integrates all kind of advertisement service providers and provide bargain function for customers that they can use it to negotiate with advertisement service providers. And AdSmart Platform make an advertisement price transparently and ensure every transactions under the law protection, so that customers do not need to worry service providers that they do not provide service after paid.', 'AdSmart_Content_23.PNG', '2024-06-30 12:40:15', '2024-06-30 13:01:54', 'AlexLam', 'Test123', 'Yes'),
(8, 'AdSmart Beliefs', 'Hope every customers can find their targeted advertisement service providers in AdSmart and Hope every Business Partners to increase their profits because of AdSmart Platform.', 'AdSmart_Content_209.PNG', '2024-06-30 15:12:19', '2024-06-30 15:14:33', 'Alex Lam', 'Admin', 'Yes'),
(9, 'AdSmart Aspiration', 'We hope to use AI function to optimize our search function that make customer to find targeted advertising service providers more accurate, promote AdSmart Platform to more country and can able to list in Hong Kong in the future.	', 'AdSmart_Content_845.PNG', '2024-06-30 15:12:19', '2024-06-30 17:04:12', 'Alex Lam', '', 'Yes'),
(10, 'Management Concept', 'Caring for the growth of employees, providing a good working environment and incentive mechanism for employees, improving training system and career development channels, enabling employees to grow delightly with Weimob, full respect and trust for employees, giving them constantly guidance and encouragement to achieve the joy of success.', 'AdSmart_Content_926.PNG', '2024-06-30 15:18:50', '2024-06-30 15:20:15', 'Alex Lam', '', 'Yes'),
(11, 'ADSMART STRENGTH', 'ADSMART STRENGTH', 'AdSmart_Content_93.PNG', '2024-06-30 15:27:19', '2024-06-30 15:28:16', 'AlexLam', 'Admin', 'Yes'),
(12, 'AdSmart Major Members', 'AdSmart Major Members', 'AdSmart_Content_35.jpg', '2024-06-30 15:28:28', '2024-06-30 15:29:15', 'AlexLam', 'Admin', 'Yes'),
(13, 'AdSmart Development History', 'AdSmart Development History', 'AdSmart_Content_40.PNG', '2024-06-30 15:28:55', '2024-06-30 15:29:04', 'AlexLam', 'Admin', 'Yes'),
(14, 'AdSmart Business Partners', 'AdSmart Business Partners', 'AdSmart_Content_717.JPG', '2024-06-30 15:36:47', '2024-06-30 15:36:56', 'AlexLam', 'Admin', 'Yes'),
(15, '', '', '', '2024-06-30 17:52:53', '0000-00-00 00:00:00', '', '', 'No');
